public class binarytrees {
    private static final int MIN_DEPTH = 4;

    private static final class Node {
        private final Node left;
        private final Node right;

        Node(Node left, Node right) {
            this.left = left;
            this.right = right;
        }

        int check() {
            return left == null ? 1 : 1 + left.check() + right.check();
        }
    }

    private static Node makeTree(int depth) {
        if (depth <= 0) {
            return new Node(null, null);
        }
        return new Node(makeTree(depth - 1), makeTree(depth - 1));
    }

    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);
        int stretchDepth = n + 1;

        Node stretchTree = makeTree(stretchDepth);
        System.out.println("stretch tree of depth " + stretchDepth
                + "\t check: " + stretchTree.check());
        stretchTree = null;

        Node longLivedTree = makeTree(n);

        for (int depth = MIN_DEPTH; depth <= n; depth += 2) {
            int iterations = 1 << (n - depth + MIN_DEPTH);
            long check = 0;

            for (int i = 0; i < iterations; i++) {
                check += makeTree(depth).check();
            }

            System.out.println(iterations + "\t trees of depth " + depth
                    + "\t check: " + check);
        }

        System.out.println("long lived tree of depth " + n
                + "\t check: " + longLivedTree.check());
    }
}
