import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class fannkuchredux {
    private static final class Result {
        final long checksum;
        final int maxFlips;

        Result(long checksum, int maxFlips) {
            this.checksum = checksum;
            this.maxFlips = maxFlips;
        }
    }

    private static final class Worker implements Callable<Result> {
        private final int n;
        private final int start;
        private final int end;
        private final int[] factorial;

        Worker(int n, int start, int end, int[] factorial) {
            this.n = n;
            this.start = start;
            this.end = end;
            this.factorial = factorial;
        }

        @Override
        public Result call() {
            int[] permutation = new int[n];
            int[] scratch = new int[n];
            int[] count = new int[n];

            firstPermutation(start, permutation, scratch, count);

            long checksum = 0;
            int maxFlips = 0;
            int sign = (start & 1) == 0 ? 1 : -1;

            for (int index = start; index < end; index++) {
                int flips = countFlips(permutation, scratch);

                checksum += (long) sign * flips;
                sign = -sign;

                if (flips > maxFlips) {
                    maxFlips = flips;
                }

                if (index + 1 < end) {
                    nextPermutation(permutation, count);
                }
            }

            return new Result(checksum, maxFlips);
        }

        private void firstPermutation(int index, int[] permutation,
                                      int[] scratch, int[] count) {
            for (int i = 0; i < n; i++) {
                permutation[i] = i;
            }

            for (int i = n - 1; i > 0; i--) {
                int rotation = index / factorial[i];
                index %= factorial[i];
                count[i] = rotation;

                System.arraycopy(permutation, 0, scratch, 0, i + 1);
                int length = i + 1;
                for (int j = 0; j < length; j++) {
                    permutation[j] = scratch[(j + rotation) % length];
                }
            }
        }

        private static void nextPermutation(int[] permutation, int[] count) {
            int first = permutation[0];
            permutation[0] = permutation[1];
            permutation[1] = first;

            int i = 1;
            while (++count[i] > i) {
                count[i] = 0;
                i++;

                first = permutation[0];
                for (int j = 0; j < i; j++) {
                    permutation[j] = permutation[j + 1];
                }
                permutation[i] = first;
            }
        }

        private static int countFlips(int[] permutation, int[] scratch) {
            int first = permutation[0];
            if (first == 0) {
                return 0;
            }

            System.arraycopy(permutation, 0, scratch, 0, permutation.length);

            int flips = 1;
            while (scratch[first] != 0) {
                int newFirst = scratch[first];
                scratch[first] = first;

                for (int left = 1, right = first - 1;
                     left < right;
                     left++, right--) {
                    int value = scratch[left];
                    scratch[left] = scratch[right];
                    scratch[right] = value;
                }

                first = newFirst;
                flips++;
            }

            return flips;
        }
    }

    public static void main(String[] args) throws Exception {
        int n = Integer.parseInt(args[0]);

        int[] factorial = new int[n + 1];
        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = factorial[i - 1] * i;
        }

        int totalPermutations = factorial[n];
        int availableProcessors = Runtime.getRuntime().availableProcessors();
        int threadCount = Math.min(Math.max(1, availableProcessors), 32);
        threadCount = Math.min(threadCount, totalPermutations);

        int taskCount = Math.min(totalPermutations, threadCount * 4);
        int chunkSize = (totalPermutations + taskCount - 1) / taskCount;

        ExecutorService executor = Executors.newFixedThreadPool(threadCount);
        List<Future<Result>> futures = new ArrayList<>(taskCount);

        try {
            for (int start = 0; start < totalPermutations; start += chunkSize) {
                int end = Math.min(start + chunkSize, totalPermutations);
                futures.add(executor.submit(
                    new Worker(n, start, end, factorial)
                ));
            }

            long checksum = 0;
            int maxFlips = 0;

            for (Future<Result> future : futures) {
                Result result = future.get();
                checksum += result.checksum;
                if (result.maxFlips > maxFlips) {
                    maxFlips = result.maxFlips;
                }
            }

            System.out.println(checksum);
            System.out.println("Pfannkuchen(" + n + ") = " + maxFlips);
        } finally {
            executor.shutdown();
        }
    }
}
