import java.io.InputStream;

public class revcomp {
    private static final byte[] COMPLEMENT = new byte[256];

    static {
        for (int i = 0; i < COMPLEMENT.length; i++) {
            COMPLEMENT[i] = (byte) i;
        }

        map('A', 'T');
        map('T', 'A');
        map('U', 'A');
        map('C', 'G');
        map('G', 'C');
        map('R', 'Y');
        map('Y', 'R');
        map('K', 'M');
        map('M', 'K');
        map('B', 'V');
        map('V', 'B');
        map('D', 'H');
        map('H', 'D');
        map('S', 'S');
        map('W', 'W');
        map('N', 'N');
    }

    private static void map(char base, char complement) {
        COMPLEMENT[base] = (byte) complement;
        COMPLEMENT[Character.toLowerCase(base)] = (byte) complement;
    }

    private static boolean isLineBreak(byte value) {
        return value == '\n' || value == '\r';
    }

    private static void reverseComplement(byte[] data, int start, int end) {
        int left = start;
        int right = end - 1;

        while (true) {
            while (left <= right && isLineBreak(data[left])) {
                left++;
            }
            while (left <= right && isLineBreak(data[right])) {
                right--;
            }

            if (left > right) {
                return;
            }

            if (left == right) {
                data[left] = COMPLEMENT[data[left] & 0xFF];
                return;
            }

            byte leftBase = data[left];
            byte rightBase = data[right];

            data[left] = COMPLEMENT[rightBase & 0xFF];
            data[right] = COMPLEMENT[leftBase & 0xFF];

            left++;
            right--;
        }
    }

    private static byte[] readAll(InputStream input) throws Exception {
        ByteArrayOutputStream output = new ByteArrayOutputStream(1 << 20);
        byte[] buffer = new byte[1 << 16];
        int count;

        while ((count = input.read(buffer)) != -1) {
            output.write(buffer, 0, count);
        }

        return output.toByteArray();
    }

    public static void main(String[] args) throws Exception {
        Integer.parseInt(args[0]);

        byte[] data = readAll(System.in);
        int length = data.length;
        int position = 0;

        while (position < length) {
            if (data[position] != '>') {
                position++;
                continue;
            }

            int sequenceStart = position;
            while (sequenceStart < length && data[sequenceStart] != '\n') {
                sequenceStart++;
            }
            if (sequenceStart < length) {
                sequenceStart++;
            }

            int nextHeader = sequenceStart;
            while (nextHeader < length) {
                if (data[nextHeader] == '>' &&
                    (nextHeader == 0 || data[nextHeader - 1] == '\n')) {
                    break;
                }
                nextHeader++;
            }

            reverseComplement(data, sequenceStart, nextHeader);
            position = nextHeader;
        }

        System.out.write(data);
    }
