import java.util.Arrays;
import java.util.Locale;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class spectralnorm {
    private static int size;
    private static int threadCount;
    private static ExecutorService executor;

    private static final class MultiplyTask implements Runnable {
        private final double[] input;
        private final double[] output;
        private final int from;
        private final int to;
        private final boolean transpose;
        private final CountDownLatch done;

        MultiplyTask(double[] input, double[] output, int from, int to,
                     boolean transpose, CountDownLatch done) {
            this.input = input;
            this.output = output;
            this.from = from;
            this.to = to;
            this.transpose = transpose;
            this.done = done;
        }

        @Override
        public void run() {
            try {
                if (transpose) {
                    multiplyTranspose();
                } else {
                    multiply();
                }
            } finally {
                done.countDown();
            }
        }

        private void multiply() {
            final int n = size;
            final double[] x = input;
            final double[] y = output;

            for (int i = from; i < to; i++) {
                int denominator = i * (i + 1) / 2 + i + 1;
                int increment = i + 1;
                int j = 0;

                double s0 = 0.0;
                double s1 = 0.0;
                double s2 = 0.0;
                double s3 = 0.0;

                for (; j + 3 < n; j += 4) {
                    s0 += x[j] / denominator;
                    denominator += increment++;

                    s1 += x[j + 1] / denominator;
                    denominator += increment++;

                    s2 += x[j + 2] / denominator;
                    denominator += increment++;

                    s3 += x[j + 3] / denominator;
                    denominator += increment++;
                }

                double sum = (s0 + s1) + (s2 + s3);
                for (; j < n; j++) {
                    sum += x[j] / denominator;
                    denominator += increment++;
                }
                y[i] = sum;
            }
        }

        private void multiplyTranspose() {
            final int n = size;
            final double[] x = input;
            final double[] y = output;

            for (int i = from; i < to; i++) {
                int denominator = i * (i + 1) / 2 + 1;
                int increment = i + 2;
                int j = 0;

                double s0 = 0.0;
                double s1 = 0.0;
                double s2 = 0.0;
                double s3 = 0.0;

                for (; j + 3 < n; j += 4) {
                    s0 += x[j] / denominator;
                    denominator += increment++;

                    s1 += x[j + 1] / denominator;
                    denominator += increment++;

                    s2 += x[j + 2] / denominator;
                    denominator += increment++;

                    s3 += x[j + 3] / denominator;
                    denominator += increment++;
                }

                double sum = (s0 + s1) + (s2 + s3);
                for (; j < n; j++) {
                    sum += x[j] / denominator;
                    denominator += increment++;
                }
                y[i] = sum;
            }
        }
    }

    private static void multiply(double[] input, double[] output,
                                 boolean transpose) throws InterruptedException {
        CountDownLatch done = new CountDownLatch(threadCount);
        int rowsPerThread = (size + threadCount - 1) / threadCount;

        for (int t = 0; t < threadCount; t++) {
            int from = t * rowsPerThread;
            int to = Math.min(size, from + rowsPerThread);
            executor.execute(new MultiplyTask(
                    input, output, from, to, transpose, done));
        }

        done.await();
    }

    private static void multiplyAtA(double[] input, double[] output,
                                    double[] temporary)
            throws InterruptedException {
        multiply(input, temporary, false);
        multiply(temporary, output, true);
    }

    public static void main(String[] args) throws Exception {
        size = Integer.parseInt(args[0]);

        int available = Runtime.getRuntime().availableProcessors();
        int useful = Math.max(1, (size + 255) / 256);
        threadCount = Math.max(1, Math.min(Math.min(available, 16), useful));
        executor = Executors.newFixedThreadPool(threadCount);

        double[] u = new double[size];
        double[] v = new double[size];
        double[] temporary = new double[size];
        Arrays.fill(u, 1.0);

        for (int iteration = 0; iteration < 10; iteration++) {
            multiplyAtA(u, v, temporary);
            multiplyAtA(v, u, temporary);
        }

        executor.shutdown();

        double numerator = 0.0;
        double denominator = 0.0;
        for (int i = 0; i < size; i++) {
            numerator += u[i] * v[i];
            denominator += v[i] * v[i];
        }

        System.out.printf(Locale.US, "%.9f%n",
                Math.sqrt(numerator / denominator));
    }
}
