        0.3029549426680,
        0.1979883004921,
        0.1975473066391,
        0.3015094502008
    };

    public static void main(String[] args) throws Exception {
        int n = Integer.parseInt(args[0]);

        byte[] iubMap = createSelectionMap(IUB_SYMBOLS, IUB_PROBABILITIES);
        byte[] homoSapiensMap =
            createSelectionMap(HOMO_SAPIENS_SYMBOLS, HOMO_SAPIENS_PROBABILITIES);

        FastOutput out = new FastOutput(System.out);

        out.writeAscii(">ONE Homo sapiens alu\n");
        out.writeRepeated(ALU, 2L * n);

        out.writeAscii(">TWO IUB ambiguity codes\n");
        int seed = out.writeRandom(3L * n, iubMap, 42);

        out.writeAscii(">THREE Homo sapiens frequency\n");
        out.writeRandom(5L * n, homoSapiensMap, seed);

        out.flush();
