    private static byte[] createSelectionMap(String symbols, double[] probabilities) {
        byte[] map = new byte[MODULUS];
        int symbolIndex = 0;
        double cumulative = probabilities[0];

        for (int value = 0; value < MODULUS; value++) {
            double r = (double) value / MODULUS;
            while (!(cumulative > r)) {
                symbolIndex++;
                cumulative += probabilities[symbolIndex];
            }
            map[value] = (byte) symbols.charAt(symbolIndex);
        }

        return map;
    }

    private static final class FastOutput {
        private static final int BUFFER_SIZE = 1 << 20;

        private final OutputStream output;
        private final byte[] buffer = new byte[BUFFER_SIZE];
        private int position;

        FastOutput(OutputStream output) {
            this.output = output;
        }

        void writeAscii(String text) throws IOException {
            byte[] bytes = text.getBytes(StandardCharsets.US_ASCII);
            int offset = 0;

            while (offset < bytes.length) {
                if (position == buffer.length) {
                    flushBuffer();
                }

                int amount = Math.min(bytes.length - offset, buffer.length - position);
                System.arraycopy(bytes, offset, buffer, position, amount);
                position += amount;
                offset += amount;
            }
        }

        void writeRepeated(byte[] sequence, long length) throws IOException {
            int sequenceIndex = 0;

            while (length > 0) {
                int lineLength = (int) Math.min(LINE_LENGTH, length);
                ensureCapacity(lineLength + 1);

                for (int i = 0; i < lineLength; i++) {
                    buffer[position++] = sequence[sequenceIndex++];
                    if (sequenceIndex == sequence.length) {
                        sequenceIndex = 0;
                    }
                }

                buffer[position++] = '\n';
                length -= lineLength;
            }
        }

        int writeRandom(long length, byte[] selectionMap, int seed)
                throws IOException {
            while (length > 0) {
                int lineLength = (int) Math.min(LINE_LENGTH, length);
                ensureCapacity(lineLength + 1);

                for (int i = 0; i < lineLength; i++) {
                    seed = (seed * MULTIPLIER + INCREMENT) % MODULUS;
                    buffer[position++] = selectionMap[seed];
                }

                buffer[position++] = '\n';
                length -= lineLength;
            }

            return seed;
        }

        private void ensureCapacity(int required) throws IOException {
            if (buffer.length - position < required) {
                flushBuffer();
            }
        }

        private void flushBuffer() throws IOException {
            if (position != 0) {
                output.write(buffer, 0, position);
                position = 0;
            }
        }

        void flush() throws IOException {
            flushBuffer();
            output.flush();
        }
    }
}
