import java.io.BufferedInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Formatter;
import java.util.List;
import java.util.Locale;

public class knucleotide {
    private static final char[] BASES = {'A', 'C', 'G', 'T'};

    private static final String[] FRAGMENTS = {
        "GGT",
        "GGTA",
        "GGTATT",
        "GGTATTTTAATT",
        "GGTATTTTAATTTATAGT"
    };

    private static final int[] FRAGMENT_LENGTHS = new int[FRAGMENTS.length];
    private static final long[] FRAGMENT_CODES = new long[FRAGMENTS.length];
    private static final long[] FRAGMENT_MASKS = new long[FRAGMENTS.length];
    private static final long[] FRAGMENT_COUNTS = new long[FRAGMENTS.length];

    private static final long[] ONE_MER_COUNTS = new long[4];
    private static final long[] TWO_MER_COUNTS = new long[16];

    private static long sequenceLength;
    private static long rollingCode;
    private static int previousBase = -1;

    private static final class Frequency {
        final String text;
        final long count;

        Frequency(String text, long count) {
            this.text = text;
            this.count = count;
        }
    }

    public static void main(String[] args) throws Exception {
        int n = Integer.parseInt(args[0]);

        initializeFragments();
        readThreeSequence();
        printResults();
    }

    private static void initializeFragments() {
        for (int i = 0; i < FRAGMENTS.length; i++) {
            String fragment = FRAGMENTS[i];
            int length = fragment.length();

            FRAGMENT_LENGTHS[i] = length;
            FRAGMENT_CODES[i] = encode(fragment);
            FRAGMENT_MASKS[i] = (1L << (length * 2)) - 1L;
        }
    }

    private static long encode(String sequence) {
        long code = 0;
        for (int i = 0; i < sequence.length(); i++) {
            code = (code << 2) | baseCode(sequence.charAt(i));
        }
        return code;
    }

    private static int baseCode(int character) {
        switch (character) {
            case 'A':
            case 'a':
                return 0;
            case 'C':
            case 'c':
                return 1;
            case 'G':
            case 'g':
                return 2;
            case 'T':
            case 't':
                return 3;
            default:
                return -1;
        }
    }

    private static boolean isThreeHeader(StringBuilder header) {
        if (header.length() < 5
                || header.charAt(0) != 'T'
                || header.charAt(1) != 'H'
                || header.charAt(2) != 'R'
                || header.charAt(3) != 'E'
                || header.charAt(4) != 'E') {
            return false;
        }

        return header.length() == 5 || Character.isWhitespace(header.charAt(5));
    }

    private static void readThreeSequence() throws IOException {
        BufferedInputStream input = new BufferedInputStream(System.in, 1 << 16);
        byte[] buffer = new byte[1 << 16];
        StringBuilder header = new StringBuilder(128);

        boolean active = false;
        boolean inHeader = false;
        boolean atLineStart = true;

        int bytesRead;
        while ((bytesRead = input.read(buffer)) != -1) {
            for (int i = 0; i < bytesRead; i++) {
                int character = buffer[i] & 0xff;

                if (inHeader) {
                    if (character == '\n' || character == '\r') {
                        active = isThreeHeader(header);
                        inHeader = false;
                        atLineStart = true;
                    } else {
                        header.append((char) character);
                    }
                    continue;
                }

                if (atLineStart && character == '>') {
                    active = false;
                    inHeader = true;
                    atLineStart = false;
                    header.setLength(0);
                    continue;
                }

                if (character == '\n' || character == '\r') {
                    atLineStart = true;
                    continue;
                }

                atLineStart = false;

                if (active) {
                    int code = baseCode(character);
                    if (code >= 0) {
                        processBase(code);
                    }
                }
            }
        }
    }

    private static void processBase(int code) {
        ONE_MER_COUNTS[code]++;

        if (previousBase >= 0) {
            TWO_MER_COUNTS[(previousBase << 2) | code]++;
        }
        previousBase = code;

        sequenceLength++;
        rollingCode = ((rollingCode << 2) | code) & FRAGMENT_MASKS[FRAGMENT_MASKS.length - 1];

        for (int i = 0; i < FRAGMENTS.length; i++) {
            if (sequenceLength >= FRAGMENT_LENGTHS[i]
                    && (rollingCode & FRAGMENT_MASKS[i]) == FRAGMENT_CODES[i]) {
                FRAGMENT_COUNTS[i]++;
            }
        }
    }

    private static void printResults() {
        StringBuilder output = new StringBuilder(1024);
        Formatter formatter = new Formatter(output, Locale.US);

        appendOneMerFrequencies(formatter);
        output.append('\n');

        appendTwoMerFrequencies(formatter);
        output.append('\n');

        for (int i = 0; i < FRAGMENTS.length; i++) {
            output.append(FRAGMENT_COUNTS[i])
                  .append('\t')
                  .append(FRAGMENTS[i])
                  .append('\n');
        }

        formatter.close();
        System.out.print(output);
    }

    private static void appendOneMerFrequencies(Formatter formatter) {
        List<Frequency> frequencies = new ArrayList<>(4);

        for (int i = 0; i < ONE_MER_COUNTS.length; i++) {
            if (ONE_MER_COUNTS[i] > 0) {
                frequencies.add(new Frequency(
                    String.valueOf(BASES[i]),
                    ONE_MER_COUNTS[i]
                ));
            }
        }

        frequencies.sort(frequencyComparator());

        for (Frequency frequency : frequencies) {
            formatter.format(
                "%s %.3f\n",
                frequency.text,
                frequency.count * 100.0 / sequenceLength
            );
        }
    }

    private static void appendTwoMerFrequencies(Formatter formatter) {
        List<Frequency> frequencies = new ArrayList<>(16);
        long total = sequenceLength - 1;

        for (int i = 0; i < TWO_MER_COUNTS.length; i++) {
            if (TWO_MER_COUNTS[i] > 0) {
                String text = new String(new char[] {
                    BASES[i >>> 2],
                    BASES[i & 3]
                });
                frequencies.add(new Frequency(text, TWO_MER_COUNTS[i]));
            }
        }

        frequencies.sort(frequencyComparator());

        for (Frequency frequency : frequencies) {
            formatter.format(
                "%s %.3f\n",
                frequency.text,
                frequency.count * 100.0 / total
            );
        }
    }

    private static Comparator<Frequency> frequencyComparator() {
        return (left, right) -> {
            int countComparison = Long.compare(right.count, left.count);
            if (countComparison != 0) {
                return countComparison;
            }
            return left.text.compareTo(right.text);
        };
    }
}
