    private static BigInteger floorDivide(BigInteger numerator, BigInteger denominator) {
        BigInteger[] result = numerator.divideAndRemainder(denominator);
        if (numerator.signum() < 0 && result[1].signum() != 0) {
            return result[0].subtract(BigInteger.ONE);
        }
        return result[0];
    }

    public static void main(String[] args) {
        int limit = Integer.parseInt(args[0]);

        BigInteger q = BigInteger.ONE;
        BigInteger r = BigInteger.ZERO;
        BigInteger t = BigInteger.ONE;

        int k = 1;
        int digit = 3;
        int l = 3;
        int count = 0;

        StringBuilder output = new StringBuilder(limit + (limit / 10 + 1) * 16);

        while (count < limit) {
            BigInteger left = q.multiply(FOUR).add(r).subtract(t);
            BigInteger right = t.multiply(BigInteger.valueOf(digit));

            if (left.compareTo(right) < 0) {
                output.append((char) ('0' + digit));
                count++;

                BigInteger oldR = r;
                r = oldR.subtract(t.multiply(BigInteger.valueOf(digit))).multiply(TEN);
                digit = floorDivide(
                        q.multiply(THREE).add(oldR).multiply(TEN),
                        t
                ).intValue() - digit * 10;
                q = q.multiply(TEN);

                if (count % 10 == 0) {
                    output.append('\t').append(':').append(count).append('\n');
                }
            } else {
                BigInteger oldQ = q;
                BigInteger oldR = r;
                BigInteger newT = t.multiply(BigInteger.valueOf(l));

                r = oldQ.multiply(TWO).add(oldR).multiply(BigInteger.valueOf(l));
                digit = floorDivide(
                        oldQ.multiply(BigInteger.valueOf(7L * k))
                                .add(TWO)
                                .add(oldR.multiply(BigInteger.valueOf(l))),
                        newT
                ).intValue();

                q = oldQ.multiply(BigInteger.valueOf(k));
                t = newT;
                k++;
                l += 2;
            }
        }

        int remainder = count % 10;
        if (remainder != 0) {
            for (int i = remainder; i < 10; i++) {
                output.append(' ');
            }
            output.append('\t').append(':').append(count).append('\n');
        }

        System.out.print(output);
    }
}
